CREATE OR REPLACE FUNCTION calculate_wage_differential(
    offered_wage NUMERIC,
    prevailing_wage NUMERIC,
    offered_unit TEXT,
    prevailing_unit TEXT
) RETURNS NUMERIC AS $$
DECLARE
    offered_annual NUMERIC;
    prevailing_annual NUMERIC;
BEGIN
    -- Convert offered wage to annual
    CASE offered_unit
        WHEN 'Hour' THEN offered_annual := offered_wage * 2080
        WHEN 'Week' THEN offered_annual := offered_wage * 52
        WHEN 'Month' THEN offered_annual := offered_wage * 12
        ELSE offered_annual := offered_wage
    END CASE;

    -- Convert prevailing wage to annual
    CASE prevailing_unit
        WHEN 'Hour' THEN prevailing_annual := prevailing_wage * 2080
        WHEN 'Week' THEN prevailing_annual := prevailing_wage * 52
        WHEN 'Month' THEN prevailing_annual := prevailing_wage * 12
        ELSE prevailing_annual := prevailing_wage
    END CASE;

    -- Return NULL if prevailing wage is 0
    IF prevailing_annual = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate WDR and round to 2 decimal places
    RETURN ROUND(((offered_annual - prevailing_annual) / prevailing_annual) * 100, 2);
END;
$$ LANGUAGE plpgsql;

